INSERT INTO divise (id, anno, stagione, tipo_home_away, foto_url, descrizione, sponsor_tecnico, sponsor_commerciale, colori, confidence, verificato, fonte_id) VALUES (1, 1986, '1986-87', 'home', '/assets/aistudio/maglia_1987_home.png', 'La maglia del primo storico Scudetto del 10 maggio 1987 e del Double con la Coppa Italia, indossata dal capitano Diego Armando Maradona. Scollo a V bianco e polsini bianchi.', 'Ennerre (NR)', 'Buitoni', 'Azzurro cielo classico con dettagli bianchi', 'alta', 1, 5);
INSERT INTO divise (id, anno, stagione, tipo_home_away, foto_url, descrizione, sponsor_tecnico, sponsor_commerciale, colori, confidence, verificato, fonte_id) VALUES (2, 1987, '1987-88', 'home', '/assets/aistudio/maglia_1988_scudetto.png', 'La prima maglia nella storia del Napoli a sfoggiare lo Scudetto tricolore cucito sul cuore e la coccarda della Coppa Italia. Iconica ed epica.', 'Ennerre (NR)', 'Buitoni', 'Azzurro cielo con Scudetto e Coccarda', 'alta', 1, 5);
INSERT INTO divise (id, anno, stagione, tipo_home_away, foto_url, descrizione, sponsor_tecnico, sponsor_commerciale, colori, confidence, verificato, fonte_id) VALUES (3, 1988, '1988-89', 'away', '/assets/aistudio/maglia_1989_uefa.png', 'La maglia bianca da trasferta della gloriosa finale di ritorno di Coppa UEFA contro lo Stoccarda al Neckarstadion (3-3), firmata dai gol di Alemão, Ferrara e Careca.', 'Ennerre (NR)', 'Mars', 'Bianco con colletto e inserti azzurri', 'alta', 1, 5);
INSERT INTO divise (id, anno, stagione, tipo_home_away, foto_url, descrizione, sponsor_tecnico, sponsor_commerciale, colori, confidence, verificato, fonte_id) VALUES (4, 1989, '1989-90', 'home', '/assets/aistudio/maglia_1990_scudetto.png', 'La maglia del secondo Scudetto, conquistato il 29 aprile 1990 al San Paolo contro la Lazio (1-0, gol di Baroni). Taglio pulito e sponsor Mars al centro.', 'Ennerre (NR)', 'Mars', 'Azzurro vivo classico', 'alta', 1, 5);
INSERT INTO divise (id, anno, stagione, tipo_home_away, foto_url, descrizione, sponsor_tecnico, sponsor_commerciale, colori, confidence, verificato, fonte_id) VALUES (5, 1997, '1997-98', 'home', '/assets/aistudio/maglia_1998_nike.png', 'La celebre divisa del debutto con sponsor tecnico Nike e sponsor commerciale Polenghi, caratterizzata da righe orizzontali azzurre tono su tono.', 'Nike', 'Polenghi', 'Azzurro royal e bianco', 'alta', 1, 5);
INSERT INTO divise (id, anno, stagione, tipo_home_away, foto_url, descrizione, sponsor_tecnico, sponsor_commerciale, colori, confidence, verificato, fonte_id) VALUES (6, 2011, '2011-12', 'home', '/assets/aistudio/maglia_2012_coppaitalia.png', 'La maglia del ritorno al successo tricolore dopo oltre vent''anni: vittoria della Coppa Italia 2012 all''Olimpico di Roma contro la Juventus imbattuta.', 'Macron', 'Lete / MSC', 'Azzurro Napoli brillante', 'alta', 1, 5);
INSERT INTO divise (id, anno, stagione, tipo_home_away, foto_url, descrizione, sponsor_tecnico, sponsor_commerciale, colori, confidence, verificato, fonte_id) VALUES (7, 2020, '2020-21', 'special', '/assets/aistudio/maglia_maradona_tribute.png', 'Maglia speciale ''Kombat Pro Buri'' a strisce verticali bianco-azzurre in omaggio all''Argentina e all''eterno legame viscerale con Diego Armando Maradona.', 'Kappa', 'Lete / MSC', 'Strisce verticali bianco e celeste albiceleste', 'alta', 1, 5);
INSERT INTO divise (id, anno, stagione, tipo_home_away, foto_url, descrizione, sponsor_tecnico, sponsor_commerciale, colori, confidence, verificato, fonte_id) VALUES (8, 2022, '2022-23', 'home', '/assets/aistudio/maglia_2023_scudetto.png', 'La maglia del terzo trionfale Scudetto, dominato e stravinto con 90 punti dalla squadra di Luciano Spalletti, Victor Osimhen e Khvicha Kvaratskhelia.', 'EA7 Emporio Armani', 'Lete / MSC', 'Azzurro profondo con logo SSC Napoli in rilievo', 'alta', 1, 5);
